head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getTotalRow]<br/>GridView 컴포넌트에 바인딩된 DataList 의 전체 Row 갯수를 반환합니다.",
    "validation" : [
        "DrillDown 적용 여부와 관계없이 DataList 의 전체 Row 갯수를 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
// DrillDown(계층) 구성 바인딩 그리드 한 개(target1)를 동적 생성한다.
//  - 부모(depth 1) 3건 + 각 부모의 자식(depth 2) 2건씩 = 6건, 전체 9건.
//  - showDepth="1" 이므로 초기엔 부모 3건만 표시되고 자식은 접힘.
//  - DrillDown 접힘/펼침과 무관하게 getTotalRow()=9 검증.
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_drill !== 'undefined') {
        $p.data.remove("dlt_drill");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="DrillDown 그리드 - 전체 9건 계층(부모 3건 + 자식 6건). showDepth=1 로 초기엔 부모 3건만 표시되고 자식은 접힘. DrillDown 접힘/펼침과 무관하게 getTotalRow() 는 9 를 반환합니다."', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // ===== DrillDown(계층) 바인딩 DataList =====
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_drill" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 계층 데이터 9건 : 부모(depth 1) 3건 + 각 부모의 자식(depth 2) 2건씩 = 6건
    let jsonDrill = [
        { "name": "영업본부", "dept": "Sales", "depth": 1 },
        { "name": "  김영업", "dept": "Sales", "depth": 2 },
        { "name": "  이영업", "dept": "Sales", "depth": 2 },
        { "name": "개발본부", "dept": "Dev",   "depth": 1 },
        { "name": "  박개발", "dept": "Dev",   "depth": 2 },
        { "name": "  최개발", "dept": "Dev",   "depth": 2 },
        { "name": "품질본부", "dept": "QA",    "depth": 1 },
        { "name": "  한품질", "dept": "QA",    "depth": 2 },
        { "name": "  서품질", "dept": "QA",    "depth": 2 }
    ];
    dlt_drill.setJSON(jsonDrill, false);

    let cList = $c.gcm.createCList({ dataList: "data:dlt_drill", checkAllType: "false" });
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="DrillDown 바인딩 그리드 (전체 9건, 초기 부모 3건 표시)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="d_hcol1" value="이름(DrillDown)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="d_hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="d_hcol3" value="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="200" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="depth" dataList="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';
    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// getTotalRow 확인 — DrillDown 그리드의 전체 Row 갯수 반환 (접힘/펼침 무관 9)
scwin.btn_getTotalRow_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("getTotalRow() : " + target1.getTotalRow());
}



// 전체 펼치기 — 표시된 부모(depth 1) 행을 toggle 하여 자식을 펼침. 펼친 후에도 getTotalRow()=9 확인
scwin.btn_expandDrill_onclick = function () {
    let cnt = target1.getTotalRow();
    for (let r = 0; r < cnt; r++) {
        if (target1.getChildrenRowIndexArray(r).length > 0 && !target1.getOpenStatus(r)) {
            target1.toggle(r);
        }
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[DrillDown 전체 펼치기 후] getTotalRow() : " + target1.getTotalRow());
}



// 전체 접기 — 펼쳐진 부모(depth 1) 행을 toggle 하여 자식을 접음. 접은 후에도 getTotalRow()=9 확인
scwin.btn_collapseDrill_onclick = function () {
    let cnt = target1.getTotalRow();
    for (let r = 0; r < cnt; r++) {
        if (target1.getChildrenRowIndexArray(r).length > 0 && target1.getOpenStatus(r)) {
            target1.toggle(r);
        }
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[DrillDown 전체 접기 후] getTotalRow() : " + target1.getTotalRow());
}
